struct Note<'a>(&'a dm_analysis::checks::Note);impl fmt::Display for Note<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{if let Some(source)=&self.0.source{write!(f,"{}:{}: {}",source.line,source.byte_column,self.0.message)}else{f.write_str(&self.0.message)}}}impl Serialize for Note<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{s.collect_str(self)}}
