struct Row<'a>(Finding<'a>,DiagnosticSeverity);impl Serialize for Row<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{use serde::ser::Error;let row=self.0.diagnostic();let point=self.0.borrowed_reported_point().map_err(S::Error::custom)?;let(path,line,column)=point.coordinates();let synthetic=self.0.is_parser_synthetic();let reader=self.0.is_reader_cursor();let span=(!synthetic&&!reader).then_some([row.span.start,row.span.end]);let expression=(!synthetic).then_some([row.expression_span.start,row.expression_span.end]);let mut out=s.serialize_struct("OriginalCallArgumentDiagnostic",10)?;out.serialize_field("family",row.family)?;out.serialize_field("severity",match self.1{DiagnosticSeverity::Error=>"error",DiagnosticSeverity::Warning=>"warning",DiagnosticSeverity::Info=>"info",DiagnosticSeverity::Hint=>"hint"})?;out.serialize_field("file",path)?;out.serialize_field("line",&line)?;out.serialize_field("column",&column)?;out.serialize_field("location_kind",if synthetic{"parser_synthetic"}else if reader{"reader_cursor"}else{"source"})?;out.serialize_field("expanded_span",&span)?;out.serialize_field("expression_span",&expression)?;out.serialize_field("message",&row.message)?;out.serialize_field("notes",&Notes(&row.notes))?;out.end()}}
fn registered_level(finding:&Finding<'_>,policy:&dm_analysis::check_policy::CheckerPolicy)->Option<DiagnosticSeverity>{let level=finding.original_fixed_level().or_else(||match finding.diagnostic().severity{dm_analysis::checks::Severity::Error=>Some(DiagnosticSeverity::Error),dm_analysis::checks::Severity::Warning=>Some(DiagnosticSeverity::Warning),dm_analysis::checks::Severity::Disabled=>None})?;policy.register(None,level)}
struct Rows<'a>{findings:&'a Findings<'a>,policy:&'a dm_analysis::check_policy::CheckerPolicy}impl Serialize for Rows<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let count=self.findings.iter().filter(|row|registered_level(row,self.policy).is_some()).count();let mut out=s.serialize_seq(Some(count))?;for row in self.findings.iter(){if let Some(level)=registered_level(&row,self.policy){out.serialize_element(&Row(row,level))?;}}out.end()}}
struct Revision(u128);impl fmt::Display for Revision{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{:032x}",self.0)}}impl Serialize for Revision{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{s.collect_str(self)}}
